pub fn dispatch_table() -> std::collections::HashMap<u32, LiftFn> {
let ext: std::collections::HashSet<u32> = EXT.iter().copied().collect();
let mut t: std::collections::HashMap<u32, LiftFn> = all().into_iter().filter(|(a, _)| !ext.contains(a)).collect();
for &(a, _, f) in crate::platform::MODELS { t.insert(a, f); } t }
